For later use we define
\begin{equation}
(x)(\theta)=
\frac
{\sinh\left(\fract{\theta}{2}+\fract{i\pi x}{2}\right)}
{\sinh\left(\fract{\theta}{2}-\fract{i\pi x}{2}\right)}~,\qquad
\phi_{(x)}(\theta)=-\frac{i}{2\pi}\frac{d}{d\theta}\ln\,(x)(\theta)=
\frac{-\sin(\pi x)/(2\pi)\,}{\cosh(\theta)-\cos(\pi x)}~,
\end{equation}
and also
\begin{equation}
\phi(\theta)=-\phi_{(\frac{1}{2})}(\theta)=\frac{1}{2\pi\cosh(\theta)}
\label{phidef}
\end{equation}
so that the staircase kernel $\phi_S(\theta)$ is
\begin{equation}
\phi_S(\theta)=\phi(\theta-\theta_0)+\phi(\theta+\theta_0)\,.
\label{phiS}
\end{equation}

define
constants $x_a$ and $y_a$ by
\begin{equation}
1+x_a=
\frac{\sin^2\Bigl(\frac{\pi a}{m+1}\Bigr)}
{\sin^2\Bigl(\frac{\pi}{m+1}\Bigr)}~~,\qquad
1+y_a=
\frac{\sin^2\Bigl(\frac{\pi a}{m}\Bigr)}
{\sin^2\Bigl(\frac{\pi}{m}\Bigr)}~.

\begin{align}
