z_{2a-3}-\alpha/2\ll\theta\ll 
z_{2a-3}+\alpha/2\,,\qquad~~~~\, a=2\dots m{-}1\,;
\label{platx}\\[4pt]
\ln(1{+}y_{a}):&~~~\,
z_{2a-2}-(\theta_0{-}\alpha)/2\ll\theta\ll 
z_{2a-2}+(\theta_0{-}\alpha)/2\,,~~~\, a=2\dots m{-}2\,,
