\,\,=\!\!
\sum_{n\ge 1\atop m+n~{\rm even}}
\frac{1}{n2^{n+2}}\,\mbox{Tr}\left(B^nJ\right)
\label{g0b}
\end{align}

For later use we note that $[B,J]=0$, and furthermore that
the eigenvector $\psi_k$ of $B$ corresponding to the
eigenvalue $\lambda_k$ satisfies 
\begin{equation}
J\psi_k=(-1)^k\psi_k\,.
\label{Jparity}
\end{equation}

